-- Traductions du catalogue en anglais, allemand, italien et espagnol, à la
-- demande d'Alexandra (18/11 : « faudrait traduire les categ », « le nom des
-- cadres aussi », « traduire dans les produits pour avancer son taf ») :
-- catégories de personnages, personnages, cadres, et 257 fiches produits
-- actives (nom court, description, titre et description Google quand la fiche
-- en a). Le texte source est celui lu sur memoryline.fr le 18/11.
--
-- Rien n'est écrasé : un champ déjà traduit par la boutique (non vide) garde
-- sa valeur ; seuls les trous se remplissent. Chaque ligne est visée par son
-- identifiant ET son nom français tel qu'il était : si Margaux a renommé
-- quelque chose entre-temps, la ligne est laissée telle quelle. Une fiche
-- produit dont la description française a changé depuis est laissée aussi
-- (empreinte md5). Tout se relit et se corrige dans le BO, langue par langue.
UPDATE "character_category" x
SET "translations" = coalesce(x."translations", '{}'::jsonb) || (
    SELECT jsonb_object_agg(l.key, l.value || coalesce((
      SELECT jsonb_object_agg(e.key, e.value)
      FROM jsonb_each(CASE WHEN jsonb_typeof(x."translations" -> l.key) = 'object' THEN x."translations" -> l.key ELSE '{}'::jsonb END) e
      WHERE jsonb_typeof(e.value) = 'string' AND btrim(e.value #>> '{}') <> ''
    ), '{}'::jsonb))
    FROM jsonb_each(t.trad) l
  )
FROM (VALUES
  (4, 'Femmes', '{"en":{"name":"Women"},"de":{"name":"Frauen"},"it":{"name":"Donne"},"es":{"name":"Mujeres"}}'::jsonb),
  (7, 'Hommes', '{"en":{"name":"Men"},"de":{"name":"Männer"},"it":{"name":"Uomini"},"es":{"name":"Hombres"}}'::jsonb),
  (1, 'Ados', '{"en":{"name":"Teens"},"de":{"name":"Teenager"},"it":{"name":"Adolescenti"},"es":{"name":"Adolescentes"}}'::jsonb),
  (5, 'Filles', '{"en":{"name":"Girls"},"de":{"name":"Mädchen"},"it":{"name":"Bambine"},"es":{"name":"Niñas"}}'::jsonb),
  (6, 'Garçons', '{"en":{"name":"Boys"},"de":{"name":"Jungen"},"it":{"name":"Bambini"},"es":{"name":"Niños"}}'::jsonb),
  (3, 'Bébés', '{"en":{"name":"Babies"},"de":{"name":"Babys"},"it":{"name":"Neonati"},"es":{"name":"Bebés"}}'::jsonb),
  (2, 'Animaux', '{"en":{"name":"Animals"},"de":{"name":"Tiere"},"it":{"name":"Animali"},"es":{"name":"Animales"}}'::jsonb),
  (10, 'Fauteuil roulant', '{"en":{"name":"Wheelchair"},"de":{"name":"Rollstuhl"},"it":{"name":"Sedia a rotelle"},"es":{"name":"Silla de ruedas"}}'::jsonb)
) AS t(id, nom, trad)
WHERE x."id" = t.id AND x."name" = t.nom;
